def solve(data: dict) -> List[int]:
    nums = data['nums']
    target = data['target']

    # Sort the array to make it easier to find pairs
    nums.sort()

    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == target:
            return [left, right]
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return []

